package com.lmspilot.learning.api;
import com.lmspilot.learning.domain.*; import com.lmspilot.support.api.ApiException; import com.lmspilot.support.security.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.*; import java.util.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
record ProgressUpdateRequest(@NotNull UUID enrollmentId,@NotNull UUID courseId,@NotNull UUID lessonId,@Min(0) @Max(100) int progressPercent,Boolean completed){} record LessonProgressResponse(UUID lessonId,int progressPercent,LearningStatus status,Instant completedAt,Instant updatedAt){} record CourseProgressResponse(UUID enrollmentId,UUID courseId,int courseVersion,int progressPercent,LearningStatus status,Instant startedAt,Instant completedAt,Instant updatedAt,List<LessonProgressResponse> lessons){} record InternalCourseProgressSummary(UUID enrollmentId,UUID courseId,int courseVersion,int progressPercent,LearningStatus status,Instant completedAt){}
@Service @Transactional class LearningProgressService {private final CourseProgressRepository courses;private final LessonProgressRepository lessons;private final IdempotencyRecordRepository keys;LearningProgressService(CourseProgressRepository c,LessonProgressRepository l,IdempotencyRecordRepository k){courses=c;lessons=l;keys=k;}List<CourseProgressResponse> mine(){return courses.findAllByUserIdOrderByUpdatedAtDesc(user()).stream().map(this::view).toList();}CourseProgressResponse detail(UUID enrollmentId){CourseProgressEntity e=courses.findByEnrollmentId(enrollmentId).orElseThrow(this::nf);if(!e.userId.equals(user()))throw new ApiException(HttpStatus.FORBIDDEN,"LEARNING_OUT_OF_SCOPE","Không được xem tiến độ của người khác");return view(e);}CourseProgressResponse update(ProgressUpdateRequest i,String key){if(key==null||key.isBlank())throw new ApiException(HttpStatus.BAD_REQUEST,"IDEMPOTENCY_KEY_REQUIRED","Thiếu Idempotency-Key");CourseProgressEntity c=courses.findByEnrollmentId(i.enrollmentId()).orElseGet(()->{CourseProgressEntity n=new CourseProgressEntity();n.enrollmentId=i.enrollmentId();n.courseId=i.courseId();n.userId=user();n.startedAt=Instant.now();return n;});if(!c.userId.equals(user()))throw new ApiException(HttpStatus.FORBIDDEN,"LEARNING_OUT_OF_SCOPE","Không được cập nhật tiến độ của người khác");if(keys.existsById(key))return view(c);LessonProgressEntity l=lessons.findByEnrollmentIdAndLessonId(i.enrollmentId(),i.lessonId()).orElseGet(()->{LessonProgressEntity n=new LessonProgressEntity();n.enrollmentId=i.enrollmentId();n.lessonId=i.lessonId();n.userId=user();return n;});l.progressPercent=i.completed()!=null&&i.completed()?100:i.progressPercent();l.status=l.progressPercent>=100?LearningStatus.COMPLETED:LearningStatus.IN_PROGRESS;l.completedAt=l.status==LearningStatus.COMPLETED?Instant.now():null;l.updatedAt=Instant.now();lessons.save(l);List<LessonProgressEntity> all=lessons.findAllByEnrollmentIdOrderByUpdatedAtAsc(i.enrollmentId());c.progressPercent=(int)Math.round(all.stream().mapToInt(x->x.progressPercent).average().orElse(0));c.status=c.progressPercent>=100?LearningStatus.COMPLETED:LearningStatus.IN_PROGRESS;c.completedAt=c.status==LearningStatus.COMPLETED?Instant.now():null;c.updatedAt=Instant.now();courses.save(c);IdempotencyRecordEntity k=new IdempotencyRecordEntity();k.idempotencyKey=key;keys.save(k);return view(c);}List<InternalCourseProgressSummary> summaries(UUID uid){return courses.findAllByUserIdOrderByUpdatedAtDesc(uid).stream().map(e->new InternalCourseProgressSummary(e.enrollmentId,e.courseId,e.courseVersion,e.progressPercent,e.status,e.completedAt)).toList();}private CourseProgressResponse view(CourseProgressEntity e){return new CourseProgressResponse(e.enrollmentId,e.courseId,e.courseVersion,e.progressPercent,e.status,e.startedAt,e.completedAt,e.updatedAt,lessons.findAllByEnrollmentIdOrderByUpdatedAtAsc(e.enrollmentId).stream().map(l->new LessonProgressResponse(l.lessonId,l.progressPercent,l.status,l.completedAt,l.updatedAt)).toList());}private ApiException nf(){return new ApiException(HttpStatus.NOT_FOUND,"LEARNING_PROGRESS_NOT_FOUND","Không tìm thấy tiến độ học");}private UUID user(){try{return CurrentUser.id();}catch(Exception e){return new UUID(0,1);}}}
@RestController @RequestMapping("/api/v1/learning") public class LearningApi {private final LearningProgressService service;public LearningApi(LearningProgressService s){service=s;}@GetMapping("/me") public List<CourseProgressResponse> mine(){return service.mine();}@GetMapping("/{enrollmentId}") public CourseProgressResponse detail(@PathVariable UUID enrollmentId){return service.detail(enrollmentId);}@PutMapping("/progress") public CourseProgressResponse update(@Valid @RequestBody ProgressUpdateRequest i,@RequestHeader(value="Idempotency-Key",required=false)String key){return service.update(i,key);} }
@RestController @RequestMapping("/internal/v1/learning") class InternalLearningController {private final LearningProgressService service;private final InternalTokenAuthorizer token;InternalLearningController(LearningProgressService s,InternalTokenAuthorizer t){service=s;token=t;}@GetMapping("/users/{userId}/courses") List<InternalCourseProgressSummary> summaries(@PathVariable UUID userId,@RequestHeader(value="X-Service-Token",required=false)String k){token.require(k);return service.summaries(userId);} }
